update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/lyon/grenoble/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"La maintenance industrielle à Grenoble et dans l''Isère","mecanisme":"Peu de bassins français empilent autant de contraintes différentes sur trente kilomètres : la microélectronique du Grésivaudan, exigeante en propreté et en traçabilité, la chimie de procédé du sud grenoblois, les papeteries en service continu, et l''héritage de la houille blanche dans le matériel électrique. Nos techniciens travaillent les utilités et les équipements de production de ces quatre mondes.","cta":"Faire chiffrer ma maintenance à Grenoble","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon siège du groupe, Montréal, Dubaï et Madrid","detail":"Aucune en Isère, des techniciens qui s''y déplacent"}]},{"type":"probleme","punchline":"Dans le Grésivaudan, ce n''est presque jamais la machine de production qui arrête la ligne. C''est un compresseur, une pompe à vide ou un groupe froid que personne ne regardait.","puces":[{"accroche":"Les utilités font tomber les procédés sensibles.","texte":"Air comprimé, vide, fluides, groupes froids : en microélectronique, une dérive d''utilité se voit sur le produit avant de se voir sur l''équipement."},{"accroche":"La propreté conditionne l''accès.","texte":"Tenue, outillage, procédure d''entrée : un technicien qui ne connaît pas ces règles ne rentre pas, ou pire, rentre mal."},{"accroche":"La chimie de procédé du sud n''a pas de fenêtre naturelle.","texte":"Service continu, installations parfois classées : l''arrêt se prépare des semaines à l''avance ou ne se fait pas."},{"accroche":"Les papeteries punissent le préventif reporté.","texte":"Rouleaux, entraînements, hydraulique : l''usure y est continue, et le rattrapage coûte plus que la visite manquée."},{"accroche":"La vallée est étroite, la compétence rare.","texte":"Entre Crolles, Voiron et le sud grenoblois, trouver un automaticien disponible prend plus de temps que la réparation elle-même."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Les utilités traitées comme des équipements critiques","texte":"air comprimé, vide, fluides, groupes froids, distribution électrique."},"benefice":"Vous fermez la cause première de la plupart des arrêts de ligne sur un site sensible."},{"prestation":{"accroche":"Le respect des règles de propreté et des habilitations du site","texte":", procédure d''entrée comprise."},"benefice":"Un intervenant extérieur cesse d''être un risque de contamination ou de non-conformité."},{"prestation":{"texte":"**Un préventif écrit, gammes et périodicités calées sur vos heures de fonctionnement.**"},"benefice":"L''arrêt subi recule, et la charge de vos électriciens et mécaniciens internes s''allège."},{"prestation":{"accroche":"Le champ technique complet","texte":"[mécanique](/expertises/mecanique/), [électricité](/expertises/electrique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/)."},"benefice":"Un seul contrat pour la mécanique de précision comme pour la chaudronnerie de procédé."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", tenue par nos techniciens mobiles, comme partout en France ([voir nos implantations](/implantations/lyon/))."},"benefice":"Les procédés continus sont couverts la nuit, le week-end et les jours fériés."},{"prestation":{"accroche":"Les grands projets pris en charge","texte":"[transfert de production](/offres/chantier/transfert-de-production/), [remise en état](/offres/retrofit/remise-en-etat/), [arrêt planifié](/offres/arret-technique/)."},"benefice":"Calages de précision, jalons datés, chiffrage écrit : le redémarrage se prépare, il ne s''espère pas."}]},{"type":"deroule","etapes":[{"titre":"Le premier contact","texte":"Vous décrivez la panne ou le besoin au 04 78 33 72 05. Rappel dans l''heure aux horaires ouvrés pour qualifier l''équipement, l''accès et les habilitations."},{"titre":"Le devis écrit","texte":"Périmètre, moyens, taux, conditions d''intervention, accepté avant le départ du technicien."},{"titre":"La préparation d''accès","texte":"Règles de propreté du site, tenue, outillage dédié, plan de prévention. Cette étape se règle avant, pas devant le sas."},{"titre":"L''intervention","texte":"Accueil sécurité, consignation, diagnostic, réparation, essais."},{"titre":"La cause racine","texte":"L''analyse cherche l''origine réelle de la défaillance, utilités comprises, pour éviter la récidive."},{"titre":"Le compte rendu","texte":"Résultats, préconisations, seuils à surveiller, versés dans votre GMAO en toute confidentialité."}]},{"type":"garanties","puces":[{"accroche":"Le périmètre dit avec franchise","texte":"nous intervenons sur les utilités et les équipements périphériques de production. Pour les procédés les plus sensibles, nous travaillons dans vos règles et avec vos habilitations, et nous le disons quand un matériel sort de notre champ."},{"accroche":"Le niveau attesté avant la première entrée en zone","texte":"entretien technique et comportemental, un candidat sur dix retenu, résultats d''évaluation communiqués en amont."},{"accroche":"Vous gardez la main","texte":"vos priorités, vos règles de sécurité, votre GMAO. Nos techniciens entrent dans votre organisation et s''y rangent, sans la redessiner."}]},{"type":"cta","question":"Besoin de savoir laquelle de vos utilités arrêtera votre ligne la prochaine fois ?","bouton":"Faire chiffrer ma maintenance à Grenoble","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/lyon/grenoble/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Un responsable maintenance intégré sur site pendant une montée de cadence","texte":"troisième trimestre 2025, reporting à la direction industrielle","lienLibelle":"Étude de cas ERIKS","lienHref":"/preuves/eriks/"},{"titre":"Techniciens intégrés aux équipes pour sécuriser la maintenance des installations","texte":"d''un équipementier automobile, en 2025","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"},{"titre":"Un automaticien SIEMENS à temps plein pour le démarrage d''une ligne neuve","texte":"deuxième et troisième trimestres 2025","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Un électromécanicien habilité risque chimique mobilisé 6 mois","texte":"remise en état d''un site de traitement des eaux industrielles","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"3 à 5 techniciens déployés dans plusieurs usines françaises, depuis septembre 2024","texte":"accompagnement d''une montée en cadence","lienLibelle":"Étude de cas VALEO : plusieurs usines","lienHref":"/preuves/valeo-usines/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous en salle blanche et en microélectronique ?","reponse":"Nous intervenons sur les utilités et les équipements périphériques de production : fluides, air comprimé, vide, mécanique, chaudronnerie, électricité, automatisme. Pour les procédés les plus sensibles, nous travaillons en milieu contrôlé, avec vos règles de propreté, vos habilitations et votre assistance au redémarrage."},{"question":"Avez-vous une agence à Grenoble ?","reponse":"Non. Migen n''a ni agence ni hub de techniciens dans le bassin grenoblois, et nous préférons le dire. Nos quatre agences sont Lyon, siège du groupe, Montréal, Dubaï et Madrid. Nos techniciens sont mobiles : ils viennent sur votre site, avec un chargé d''affaires qui connaît votre dossier."},{"question":"Couvrez-vous toute l''Isère ?","reponse":"Oui : Grenoble, Saint-Martin-d''Hères, Saint-Égrève, Crolles et le Grésivaudan, Voiron, le sud grenoblois jusqu''au Pont-de-Claix. Nos techniciens se déplacent aussi vers Lyon, Valence, la Haute-Savoie et la France entière, avec un contrat unique et des comptes rendus au même format."},{"question":"Quel délai pour une intervention à Grenoble ?","reponse":"Aucun délai de façade ne figure sur cette page. Ce que nous tenons : un rappel dans l''heure aux horaires ouvrés, une qualification assez précise pour éviter un second déplacement, et l''astreinte 24/24 et 7/7 en option la nuit, le week-end et les jours fériés. Le circuit et les priorités s''écrivent au devis."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"Zéro arrêt est chiffré sur devis, avec trois niveaux de couverture et un engagement type de 6 mois renouvelable. Le chiffrage se fait après une pré-visite : équipements couverts, utilités incluses, fréquences, astreinte. Un site soumis à des règles de propreté se chiffre pour ce qu''il demande vraiment. Diagnostic de départ gratuit."},{"question":"Pouvez-vous affecter un technicien à demeure sur notre site ?","reponse":"Oui, avec l''offre [résidence](/offres/residence/) : un salarié Migen qui rejoint votre équipe, suivi par un référent, en poste sous 2 à 3 semaines. Absence ou départ, un profil équivalent prend le relais, briefé sur vos installations."},{"question":"Externaliser, est-ce céder le pilotage de notre parc ?","reponse":"Pas si le cadre est posé. Périmètre défini, comptes rendus partagés, taux de disponibilité relevés à chaque visite. Beaucoup de sites commencent par un dépannage, puis un chantier, puis un contrat. Notre ressource [externaliser sa maintenance](/ressources/livres-blancs/externaliser-sa-maintenance/) détaille les points à verrouiller avant de signer."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser un site où chaque heure d''arrêt se paie très cher ?","bouton":"Faire chiffrer ma maintenance à Grenoble","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/lyon/grenoble/';
